// HomeBody Service Worker. The cache name is the release identifier: VERSION is a content hash
// written by scripts/stamp-sw.mjs (npm run stamp), never edited by hand.
// >>> stamp-sw:begin (generated by scripts/stamp-sw.mjs; run `npm run stamp`, do not edit)
const VERSION = 'c46f7a056097';
const PRECACHE = ["fonts/inter-latin.woff2", "fonts/oswald-latin.woff2", "icon-192.png", "icon-512.png", "index.html", "manifest.json", "src/hb-storage.js"];
// <<< stamp-sw:end
const CACHE = 'homebody-' + VERSION;

// All paths in PRECACHE are relative to this script, so the GitHub Pages sub-path just works.
const INDEX = 'index.html';

self.addEventListener('install', event => {
  // Fetch everything first ('reload' bypasses the HTTP cache so one release never mixes files),
  // reject any non-ok or redirected answer, and only then open the cache and store. If anything
  // fails the install fails, no homebody-<VERSION> cache is left behind, and the previous worker
  // and cache stay in charge (never a partial cache).
  event.waitUntil((async () => {
    const responses = await Promise.all(PRECACHE.map(async u => {
      const req = new Request(u, { cache: 'reload' });
      const res = await fetch(req);
      if (!res.ok || res.redirected) throw new Error('precache failed: ' + u + ' (' + res.status + ')');
      return [req, res];
    }));
    try {
      const cache = await caches.open(CACHE);
      await Promise.all(responses.map(([req, res]) => cache.put(req, res)));
    } catch (err) {
      await caches.delete(CACHE);
      throw err;
    }
  })());
});

self.addEventListener('activate', event => {
  // Only this app's old caches: the github.io origin is shared with other projects.
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys.filter(k => k.startsWith('homebody-') && k !== CACHE).map(k => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never intercept third parties

  if (req.mode === 'navigate') {
    // The shell is one document: serve the precached index.html whatever the query string.
    event.respondWith(
      caches.open(CACHE).then(cache =>
        cache.match(INDEX, { ignoreSearch: true }).then(hit => hit || fetch(req))
      )
    );
    return;
  }
  // ignoreSearch is safe for assets: they are content-hashed with the release, so ?v= never selects a different file.
  event.respondWith(
    caches.open(CACHE).then(cache =>
      cache.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req))
    )
  );
});

// A new worker waits until the page asks (or every window of the scope has closed): there is no
// skipWaiting() at install, so an update never takes over a running workout (ADR 0003, T4).
self.addEventListener('message', event => {
  const d = event.data;
  if (d === 'skipWaiting' || (d && d.type === 'SKIP_WAITING')) { // the string is what pre-M1 pages send
    self.skipWaiting();
  } else if (d && d.type === 'GET_VERSION' && event.ports && event.ports[0]) {
    event.ports[0].postMessage(VERSION); // local only, no network
  }
});
